CREATE TABLE holidays (id UUID DEFAULT RANDOM_UUID() PRIMARY KEY, holiday_date DATE UNIQUE NOT NULL, name VARCHAR(160) NOT NULL, optional BOOLEAN NOT NULL DEFAULT FALSE, created_by UUID REFERENCES users(id));
CREATE TABLE attendance_records (id UUID DEFAULT RANDOM_UUID() PRIMARY KEY, employee_id UUID NOT NULL REFERENCES employees(id) ON DELETE CASCADE, attendance_date DATE NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'PRESENT', check_in TIMESTAMP WITH TIME ZONE, check_out TIMESTAMP WITH TIME ZONE, overtime_hours DECIMAL(6,2) DEFAULT 0, remarks VARCHAR(500), created_by UUID REFERENCES users(id), UNIQUE(employee_id,attendance_date));
CREATE TABLE leave_requests (id UUID DEFAULT RANDOM_UUID() PRIMARY KEY, employee_id UUID NOT NULL REFERENCES employees(id) ON DELETE CASCADE, leave_type VARCHAR(40) NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, days DECIMAL(6,2) NOT NULL, reason VARCHAR(500), status VARCHAR(20) NOT NULL DEFAULT 'PENDING', approved_by UUID REFERENCES users(id), created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE payroll_runs (id UUID DEFAULT RANDOM_UUID() PRIMARY KEY, run_month DATE NOT NULL UNIQUE, status VARCHAR(20) NOT NULL DEFAULT 'DRAFT', total_gross DECIMAL(15,2) NOT NULL DEFAULT 0, total_deductions DECIMAL(15,2) NOT NULL DEFAULT 0, total_net DECIMAL(15,2) NOT NULL DEFAULT 0, finalized_by UUID REFERENCES users(id), finalized_at TIMESTAMP WITH TIME ZONE);
CREATE TABLE payroll_items (id UUID DEFAULT RANDOM_UUID() PRIMARY KEY, payroll_run_id UUID NOT NULL REFERENCES payroll_runs(id) ON DELETE CASCADE, employee_id UUID NOT NULL REFERENCES employees(id), basic_salary DECIMAL(15,2) NOT NULL DEFAULT 0, hra DECIMAL(15,2) NOT NULL DEFAULT 0, incentives DECIMAL(15,2) NOT NULL DEFAULT 0, commission DECIMAL(15,2) NOT NULL DEFAULT 0, bonus DECIMAL(15,2) NOT NULL DEFAULT 0, pf DECIMAL(15,2) NOT NULL DEFAULT 0, esic DECIMAL(15,2) NOT NULL DEFAULT 0, professional_tax DECIMAL(15,2) NOT NULL DEFAULT 0, loan_recovery DECIMAL(15,2) NOT NULL DEFAULT 0, gross_salary DECIMAL(15,2) NOT NULL DEFAULT 0, total_deductions DECIMAL(15,2) NOT NULL DEFAULT 0, net_salary DECIMAL(15,2) NOT NULL DEFAULT 0, payment_status VARCHAR(20) NOT NULL DEFAULT 'PENDING', payment_date DATE, payment_mode VARCHAR(30), UNIQUE(payroll_run_id,employee_id));
